  'step-change',
  $cfg${"meta":{"title":"וובינר השקעות בשוק ההון למתחילים | עם מנכ\"ל אלטשולר שחם טרייד","description":"75 דקות שיסבירו איך שוק ההון עובד, כמה כסף מתאים לכם להשקיע ואיך מודדים סיכון. עם אבי מלכא ופישל רוזנפלד. ללא עלות."},"brand":{"logoUrl":"/logo-hamechadesh.png","name":"המחדש","tagline":"צעד קטן, שינוי גדול"},"hero":{"eyebrow":"וובינר חי | שוק ההון למתחילים | ללא עלות","eyebrowLogoUrl":"","headline":"לפני שהכסף שלכם יישאר בעו\"ש עוד שנה שלמה —","headlineAccent":"בואו להבין איך זה באמת עובד","subheadline":"","description":"וובינר פתוח למי שיש לו קצת כסף בצד ורוצה סוף סוף להבין מה עושים איתו. בעברית פשוטה, עם ארבע תשובות ברורות:","ctaText":"תשמרו לי מקום בוובינר"},"webinar":{"dateISO":"2026-08-29T19:00:00.000Z","dateLabel":"מוצ\"ש, 29/8 · בשעה 22:00 · 75 דקות בזום","dayShort":"מוצ\"ש","dateShort":"29/8","time":"22:00","venue":"וובינר Zoom חי","venueShort":"Zoom","spotsLimited":true},"intro":{"eyebrow":"","title":"","titleAccent":"","body":"","highlights":[]},"speakers":{"eyebrow":"המרצים","title":"מי עומד מאחורי המפגש","titleAccent":"","intro":"","list":[{"name":"אבי מלכא","role":"מנכ\"ל אלטשולר שחם טרייד","bio":"אחרי שנים כמנהל אגף שוק ההון בבנק, נבחר להקים מאפס את פעילות המסחר העצמאי של אלטשולר שחם ולנהל אותה כמנכ\"ל.\n\nהוא רואה כל יום מה עושים משקיעים ישראלים בפועל — מה עובד להם, ואיפה הם נופלים שוב ושוב.","photoUrl":"/templates/step-change/avi_malka.jpeg","logoUrl":"","accent":"primary","highlights":[]},{"name":"פישל רוזנפלד","role":"מומחה ויועץ לכלכלת המשפחה","bio":"מחבר הספר \"פלוס מינוס\", יועץ ומאמן לכלכלת המשפחה, ומי שליווה משפחות רבות בדרך מהמינוס לניהול כלכלי מסודר.\n\nהוא מדבר על התקציב שיש לכם באמת, ועל מה נכון לעשות איתו בשלב הזה.","photoUrl":"/templates/step-change/fishel.jpg","logoUrl":"","accent":"primary","highlights":[]},{"name":"ישראל בוגרד","role":"מנחה הוובינר","bio":"איש תקשורת ויוצר תוכן, מעל 10 שנים בעולם הדיגיטלי.","photoUrl":"/templates/step-change/israel_bograd.jpg","logoUrl":"","accent":"primary","highlights":[]}]},"bullets":{"eyebrow":"מה תקבלו בהרצאה","title":"","titleAccent":"","intro":"","items":[]},"commitments":{"enabled":false,"eyebrow":"","title":"","titleAccent":"","body":"","imageUrl":""},"form":{"eyebrow":"הרשמה למפגש","title":"שומרים לכם מקום","titleAccent":"","description":"שלושה פרטים, פחות מדקה, ואתם בפנים.","bullets":[],"cardTitle":"תשמרו לי מקום בוובינר","cardDescription":"מספר המקומות מוגבל · ההרשמה אינה כרוכה בתשלום · ניתן להסיר בכל עת","buttonText":"תשמרו לי מקום בוובינר"},"footer":{"phone":"","email":"","legal":"© המחדש 2026"},"theme":{"primary":"#0B1437","primary2":"#1B2762","accent":"#F5B500","accentLight":"#FFCB3D","purple":"#7C3AED","coral":"#FB7185","dark":"#0A0E27"},"stepChange":{"topbarCta":"הצטרפות","brandChip":"אלטשולר שחם","brandChipStrong":"טרייד","heroChips":["מוצ\"ש, 29/8","22:00","75 דקות","בזום","ללא עלות"],"heroCtaNote":"ההרשמה אורכת פחות מדקה · ללא עלות · מספר המקומות מוגבל","typingQuestions":["מה בכלל קורה שם מאחורי הקלעים של השוק?","כמה כסף צריך כדי להתחיל — ומה קורה אם יש לי מעט?","איך מודדים סיכון עוד לפני שקונים?","מה הצעד הראשון שאני עושה מחר בבוקר?"],"trust":[{"value":"20+ שנה","label":"ניסיון בשוק ההון של אבי מלכא"},{"value":"מנכ\"ל","label":"אלטשולר שחם טרייד"},{"value":"10+ שנים","label":"פישל רוזנפלד בליווי כלכלי למשפחות"},{"value":"75 דקות","label":"כולל שו\"ת פתוח בשידור חי"}],"pain":{"eyebrow":"נשמע מוכר?","title":"כל אחד מסביבכם מדבר על השקעות.\nואתם עדיין","titleAccent":"באותו מקום.","dragLabel":"גררו לצדדים","quotes":["\"יש לי קצת כסף בצד, ואני פשוט לא יודע איפה לשים אותו.\"","\"כולם מדברים על מדד אמריקאי כלשהו. אני לא מבין על מה.\"","\"אני נכנס לאתר של הבנק, ויוצא יותר מבולבל ממה שנכנסתי.\"","\"אני מפחד להפסיד דווקא את הכסף שחסכתי בקושי.\"","\"שאלתי חבר, הוא אמר לי לקנות משהו. לא הבנתי מה קניתי.\"","\"אין לי מאה אלף שקל. אז זה בכלל לא בשבילי, נכון?\"","\"כל שנה אני אומר שהשנה אני אלמד את זה. וזהו.\"","\"אני לא רוצה להיכנס למשהו שאני לא מבין לעומק.\"","\"מי שמסביר לי את זה תמיד מנסה למכור לי משהו.\"","\"אני מרגיש שאני מפספס, ואין לי מושג מה בדיוק.\""],"closing":"ההבנה שחסרה לכם נמצאת במרחק 75 דקות.","cta":"תשמרו לי מקום בוובינר","ctaNote":"ללא עלות · ניתן לצאת בכל רגע · מקבלים גם את ההקלטה"},"bridge":{"eyebrow":"הנקודה שבה זה משתנה","title":"הכללים של שוק ההון פשוטים ממה שנדמה.\nצריך רק מי שיסביר אותם בגובה העיניים.","body1":"שוק ההון נבנה כדי להיות מקצועי, והמקצועיות הזאת נשמעת מסובכת מבחוץ. מה שמכריע כמעט תמיד זה מי הסביר לכם מה קורה שם, ובאיזו שפה.","body2":"במפגש הזה שני אנשים יסבירו לכם בדיוק את זה. אחד מנהל פלטפורמת מסחר של בית השקעות. השני יושב מול משפחות ומתרגם כסף לשפה של תקציב אמיתי.","punch":"הכללים עצמם, בשפה שלכם."},"agenda":{"eyebrow":"תוכנית המפגש","title":"שישה נושאים. שבעים וחמש דקות.\nמתחילים מהתחלה.","modules":[{"n":"01","title":"מאיפה מתחילים","promise":"בסוף החלק הזה תדעו בדיוק מה צריך כדי לפתוח חשבון מסחר.","detail":"מה זה חבר בורסה, מה ההבדל מול הבנק, מה נדרש מכם בפועל, וכמה זמן זה באמת לוקח.","tag":""},{"n":"02","title":"השפה של השוק, בעברית","promise":"מניה, אג\"ח, קרן סל, מדד — כל מונח בעברית פשוטה.","detail":"ההסבר במונחים של החיים האמיתיים. אחריו תבינו כל כותרת כלכלית בעיתון.","tag":""},{"n":"03","title":"סיכון: מה זה באמת אומר","promise":"תלמדו איך מודדים סיכון עוד לפני שקונים.","detail":"למה כל השקעה כרוכה בסיכון, מה ההבדל בין תנודתיות להפסד, ומה זה אומר לגבי הכסף של המשפחה שלכם.","tag":""},{"n":"04","title":"כמה כסף מתאים לכם — עם פישל רוזנפלד","promise":"תצאו עם דרך לחשב מה מותר לכם להשקיע, מתוך התקציב שלכם.","detail":"קרן חירום קודם, השקעה אחר כך. איפה עובר הגבול, ואיך יודעים שהגעתם אליו. החלק הכי חשוב למשפחות עם הכנסה בינונית.","tag":"החלק של פישל"},{"n":"05","title":"חמש הטעויות של השנה הראשונה","promise":"תזהו מראש את הטעויות שמתחילים עושים כמעט תמיד.","detail":"מה קורה כשקונים לפי טיפ מחבר, למה תזמון השוק לא עובד, ומה עושים כשהמסך אדום.","tag":""},{"n":"06","title":"מהמסך: איך זה נראה בפועל","promise":"תראו בשידור חי איך נראית פעולה במערכת מסחר.","detail":"אבי מלכא מציג את המסכים עצמם — מה רואים, מה לוחצים, ואיפה אנשים נתקעים.","tag":""}],"qaNote":"+ שו\"ת פתוח בסוף המפגש. אתם שואלים, הם עונים בשידור.","closing":"וזו רק תוכנית הבסיס. את החלק המעניין באמת שואלים המשתתפים.","cta":"הצטרפות","ctaNote":"75 דקות · בזום · ללא עלות · ההקלטה נשלחת לכל הנרשמים"},"risk":{"eyebrow":"בואו נדבר על מה שבאמת מטריד","titleAccent":"\"ואם אני אפסיד את הכסף?\"","title":"זו השאלה הנכונה, ויש לה תשובה מלאה.","body1":"כל מי שמבטיח לכם רווח בטוח בשוק ההון — מוכר לכם משהו. השקעה בשוק ההון כרוכה בסיכון, ואפשר להפסיד חלק מהכסף או את כולו. זו לא אזהרה בקטן למטה. זה הדבר הראשון שצריך להבין.","body2":"אפשר ללמוד להסתכל על הסיכון הזה בעיניים פקוחות: מה ההבדל בין ירידה זמנית להפסד ממומש, כמה כסף נכון להעמיד בסיכון בשלב הזה של החיים שלכם, ומה עושים ביום שבו המסך אדום.","punch":"זה בדיוק מה שהמפגש הזה מלמד: שיקול דעת.","badHead":"מיתוסים נפוצים","goodHead":"מה תקבלו כאן","rows":[{"bad":"הבטחת תשואה","good":"הסבר איך נמדד סיכון"},{"bad":"\"מניה שחייבים לקנות\"","good":"כלים להחליט לבד"},{"bad":"לחץ לפתוח חשבון היום","good":"זמן לשאול שאלות"}]},"speakersEyebrow":"מי עומד מאחורי המפגש","speakersTitle":"פאנל המומחים","speakerCards":[{"badge":"20+","meta":"20 שנות ניסיון בשוק ההון","punch":"מי שמנהל את המערכת מסביר איך היא עובדת."},{"badge":"10+","meta":"10 שנים בליווי כלכלי של משפחות","punch":"את השוק לומדים פעם אחת. את התקציב חיים איתו כל יום."},{"badge":"10+","meta":"מעל 10 שנים בעולם הדיגיטלי","punch":"תפקידו במפגש פשוט: לוודא שכל שאלה מקבלת תשובה, וכל מונח מקבל הסבר."}],"audience":{"eyebrow":"אולי אחד מהם זה אתם","title":"המפגש הזה נבנה בשביל אנשים,\nבשפה של אנשים.","cards":[{"quote":"יש לי קרן השתלמות נזילה שלוש שנים ואני לא נוגע בה.","note":"— כי אף אחד לא הסביר מה האפשרויות","dark":false},{"quote":"אני מרוויח בסדר, אבל בסוף החודש לא נשאר כלום להשקיע.","note":"— החלק של פישל נכתב בדיוק בשבילכם","dark":true},{"quote":"אני בן 26, יש לי עשרת אלפים שקל, וזה נראה לי מעט מדי.","note":"— זה בדיוק הסכום שבו מתחילים ללמוד","dark":false},{"quote":"בעלי אומר שנשקיע, ואני חוששת שנפסיד.","note":"— בואו שניכם. תשמעו את שני הצדדים","dark":false},{"quote":"פתחתי חשבון מסחר לפני שנה ולא עשיתי בו כלום.","note":"— נראה לכם על המסך איך זה עובד","dark":false},{"quote":"אני בן 52 ומרגיש שאיחרתי את הרכבת.","note":"— לא איחרתם. משנים את שאלות התכנון","dark":false},{"quote":"כבר קניתי משהו פעם, הפסדתי, ומאז אני בחוץ.","note":"— נדבר בדיוק על מה שקרה שם","dark":false}],"footnote":"המפגש בנוי למי שעושה את הצעדים הראשונים שלו בשוק ההון, ורוצה לעשות אותם בהבנה."},"proof":{"eyebrow":"למה להקשיב דווקא להם","title":"הסמכות כאן מגיעה מהשטח.","items":[{"value":"20+ שנות ניסיון","label":"אבי מלכא בשוק ההון הישראלי, בבנקאות ובבתי השקעות"},{"value":"בית השקעות מוביל","label":"אלטשולר שחם טרייד — פלטפורמת מסחר עצמאי בשוק ההון בישראל ובארה\"ב"},{"value":"ספר, פודקאסט וקהילה","label":"פישל רוזנפלד מלווה משפחות בכלכלת הבית ומחבר הספר \"פלוס מינוס\""}],"testimonials":"","punch":"כאן יושבים אנשים שעושים את זה כל יום."},"perks":{"eyebrow":"רק למי שנמצא בשידור","title":"החלק שקורה רק","titleAccent":"בשידור החי","body1":"בסוף המפגש נפתח שו\"ת חי. כל אחד שואל את מה שבאמת מפריע לו, ומקבל תשובה ישירה ממי שיושב בצד השני של השוק.","body2":"אלה השאלות שרק אתם יכולים לשאול, כי הן שלכם.","cta":"תשמרו לי מקום בוובינר","ctaNote":"ההרשמה ללא עלות · ניתן לבטל בקליק","items":[{"n":"01","title":"ההקלטה המלאה","body":"נשלחת לכל מי שנרשם, גם אם לא הצלחתם להתחבר בזמן.","highlight":false},{"n":"02","title":"מסמך המושגים","body":"כל המונחים מהמפגש בעמוד אחד, בעברית פשוטה. נשלח במייל אחרי.","highlight":false},{"n":"03","title":"הטבה בלעדית למשתתפים","body":"","highlight":true}],"note":"מספר המשתתפים בשידור מוגבל לפי קיבולת הפלטפורמה."},"ctaBand":{"title":"שעה אחת עכשיו.\nושנה שלמה של החלטות טובות יותר.","body":"ההחלטה היחידה שצריך לקבל היום היא להבין על מה מדובר.","cta":"תשמרו לי מקום בוובינר","note":"פחות מדקה להרשמה · ללא עלות · ההקלטה נשלחת לכולם"},"register":{"eyebrow":"הרשמה למפגש","title":"שומרים לכם מקום","body":"שלושה פרטים, פחות מדקה, ואתם בפנים.","details":[{"label":"מתי","value":"מוצ\"ש, 29/8, בשעה 22:00"},{"label":"כמה זמן","value":"75 דקות כולל שו\"ת"},{"label":"איפה","value":"בזום — הקישור נשלח במייל ובוואטסאפ"},{"label":"עלות","value":"ללא עלות"}],"legal":"התוכן במפגש הוא כללי ולימודי בלבד ואינו מהווה ייעוץ או שיווק השקעות או תחליף לייעוץ אישי המתחשב בנתוניו וצרכיו של כל אדם. השקעה בשוק ההון כרוכה בסיכון, לרבות אפשרות להפסד חלק מכספי ההשקעה או כולם."},"faqTitle":"מה שעוד לא שאלתם","faq":[{"q":"זה וובינר מכירתי? ינסו למכור לי משהו בסוף?","a":"המפגש הוא לימודי. יש בו הטבה למשתתפים שנציג בשקיפות בסוף, ואין בו חובת רכישה, שיחת מכירה שנכפית עליכם, או לחץ לפתוח חשבון. אתם מקבלים את התוכן המלא בין אם תעשו משהו אחרי ובין אם לא."},{"q":"ומה אם אני לא יכול להתחבר בשעה הזו?","a":"תירשמו בכל זאת. ההקלטה המלאה נשלחת לכל הנרשמים במייל, יחד עם מסמך המושגים. מה שלא תקבלו זה את השו\"ת החי — הוא לא נכנס להקלטה."},{"q":"אין לי הרבה כסף להשקיע. זה עדיין רלוונטי לי?","a":"כן, ובמידה מסוימת דווקא יותר. חלק שלם במפגש, עם פישל רוזנפלד, עוסק בשאלה כמה כסף בכלל נכון להעמיד להשקעה מתוך תקציב משפחתי, ומתי התשובה הנכונה היא \"עדיין לא\". זה בדיוק הידע שחוסר בו עולה כסף."},{"q":"שוק ההון זה לא הימור? אני עלול לאבד את הכסף.","a":"השקעה בשוק ההון כרוכה בסיכון, וכן — אפשר להפסיד חלק מהכסף או את כולו. המפגש לא מבטיח לכם רווח ולא ממליץ לכם על השקעה מסוימת. הוא מלמד איך מסתכלים על סיכון, איך מודדים אותו, ואיך מחליטים החלטה בעיניים פקוחות."},{"q":"אין לי שום רקע בכלכלה. ארגיש שאני לא מבין כלום?","a":"המפגש נבנה מאפס ידע קודם. כל מונח מוסבר בעברית פשוטה לפני שמשתמשים בו, ותפקידו של המנחה לעצור בכל פעם שמשהו נשמע מסובך מדי. תקבלו גם מסמך עם כל המושגים אחרי המפגש."},{"q":"איך אני יודע שהמידע שלי לא ידלוף לכל מיני מפרסמים?","a":"הפרטים משמשים לשליחת קישור לשידור, תזכורת וההקלטה. אפשר להסיר את עצמכם מרשימת הדיוור בקליק אחד בכל מייל שתקבלו."}],"final":{"title":"צעד קטן. שינוי גדול.","titleAccent":"השעה הזאת היא הצעד.","mono":"29/8 במוצ\"ש, 22:00, 75 דקות. בזום. ללא עלות.","cta":"תשמרו לי מקום בוובינר","credit":"וובינר \"צעד קטן, שינוי גדול\" · בהנחיית ישראל בוגרד","legal":"התוכן במפגש הוא כללי ולימודי בלבד ואינו מהווה ייעוץ השקעות, שיווק השקעות או תחליף לייעוץ אישי המתחשב בנתוניו ובצרכיו של כל אדם. השקעה בשוק ההון כרוכה בסיכון, לרבות אפשרות להפסד חלק מכספי ההשקעה או כולם. אין בתוצאות העבר כדי להעיד על תוצאות העתיד.","copyright":"© המחדש 2026"},"stickyCta":"תשמרו לי מקום בוובינר","stickyNote":"מוצ\"ש 29/8 · 22:00 · ללא עלות"},"banner":{"imageUrl":"","linkUrl":"","alt":""},"integrations":{"sendmsg":{"enabled":true,"listName":""}},"styleOverrides":{}}$cfg$,
